internal sealed partial class ModernWorkspace {
 readonly List<GoogleCalendarInfo> calendarSources=new List<GoogleCalendarInfo>();readonly List<GoogleCalendarEvent> calendarEvents=new List<GoogleCalendarEvent>();DateTime calendarFrom,calendarUntil,calendarAttempt=DateTime.MinValue;string calendarAccount="",calendarLoadedId="";
 GoogleCalendarClient CalendarApi{get{return new GoogleCalendarClient(GoogleClient.Api);}}
 GoogleSession CalendarSession(){try{var session=GoogleClient.Vault.Read<GoogleSession>("session");if(session==null||!session.scope.Contains("calendar.events"))return null;return session;}catch{return null;}}
 void GoogleCalendarSection(StackPanel body){
  var panel=new StackPanel();var session=CalendarSession();var tools=new WrapPanel();tools.Children.Add(Btn("Configurer Google Agenda",delegate{Go("Google Drive");},false,true));
  if(session==null){calendarEvents.Clear();calendarSources.Clear();calendarAccount="";panel.Children.Add(T("Connectez ou reconnectez Google pour retrouver vos événements ici.",12,Muted));}
  else{
   if(calendarAccount!=""&&calendarAccount!=session.email){calendarEvents.Clear();calendarSources.Clear();calendarLoadedId="";}calendarAccount=session.email;
   if(calendarSources.Count>0){var picker=new ComboBox{ItemsSource=calendarSources.Select(c=>c.summary).ToList(),Width=220,SelectedIndex=calendarSources.FindIndex(c=>c.id==store.Value.settings.GoogleCalendarId),Margin=new Thickness(0,0,8,0)};picker.SelectionChanged+=delegate{if(picker.SelectedIndex<0)return;var c=calendarSources[picker.SelectedIndex];store.Value.settings.GoogleCalendarId=c.id;owner.Save();SyncGoogleCalendar();};tools.Children.Add(picker);}
   var sync=Btn(googleBusy?"Actualisation…":"Actualiser Google",delegate{SyncGoogleCalendar();},false,true);sync.IsEnabled=!googleBusy;tools.Children.Add(sync);
   var current=calendarSources.FirstOrDefault(c=>c.id==store.Value.settings.GoogleCalendarId);if(GoogleCalendarClient.CanWrite(current)){var add=Btn("+ Événement Google",delegate{EditGoogleEvent(null);},true);add.IsEnabled=!googleBusy;tools.Children.Add(add);}
   panel.Children.Add(T("Google Agenda · "+session.email+(calendarLoadedId==store.Value.settings.GoogleCalendarId?" · actualisé à "+calendarAttempt.ToLocalTime().ToString("HH:mm"):""),11,Muted,new Thickness(0,0,0,12)));
   var first=new DateTime(agendaDate.Year,agendaDate.Month,1).AddDays(-7);if(!owner.IsPreview&&!googleBusy&&(calendarLoadedId!=store.Value.settings.GoogleCalendarId||calendarFrom!=first||DateTime.UtcNow-calendarAttempt>TimeSpan.FromMinutes(2))&&DateTime.UtcNow-calendarAttempt>TimeSpan.FromSeconds(30))Dispatcher.BeginInvoke((Action)SyncGoogleCalendar);
  }panel.Children.Add(tools);if(!String.IsNullOrEmpty(googleMessage))panel.Children.Add(T(googleMessage,11,Muted,new Thickness(0,12,0,0)));var card=Card("Google Agenda",panel);card.Margin=new Thickness(0,0,0,20);body.Children.Add(card);
 }
 void SyncGoogleCalendar(){if(googleBusy||CalendarSession()==null)return;calendarAttempt=DateTime.UtcNow;string id=store.Value.settings.GoogleCalendarId;var from=new DateTime(agendaDate.Year,agendaDate.Month,1).AddDays(-7);GoogleOperation(async token=>{var calendars=await CalendarApi.Calendars(token);var selectedCalendar=calendars.FirstOrDefault(c=>c.id==id);if(selectedCalendar==null)selectedCalendar=calendars.FirstOrDefault(c=>c.primary)??calendars.FirstOrDefault();if(selectedCalendar==null)throw new InvalidOperationException("Aucun agenda accessible sur ce compte.");var events=await CalendarApi.Events(selectedCalendar.id,from,from.AddMonths(1).AddDays(14),token);token.ThrowIfCancellationRequested();calendarSources.Clear();calendarSources.AddRange(calendars);calendarEvents.Clear();calendarEvents.AddRange(events);calendarFrom=from;calendarUntil=from.AddMonths(1).AddDays(14);calendarLoadedId=selectedCalendar.id;store.Value.settings.GoogleCalendarId=selectedCalendar.id;owner.Save();googleMessage=events.Count+" événement(s) Google chargé(s).";},"Actualisation de Google Agenda…");}
 void AppendGoogleDay(StackPanel body,DateTime day){
  if(CalendarSession()==null||calendarLoadedId!=store.Value.settings.GoogleCalendarId)return;
  if(day<calendarFrom||day>=calendarUntil){body.Children.Add(T("Actualisez Google Agenda pour cette période.",11,Muted));return;}
  foreach(var item in calendarEvents){DateTime start,end;try{start=GoogleCalendarClient.LocalStart(item);end=GoogleCalendarClient.LocalStart(new GoogleCalendarEvent{start=item.end});}catch{continue;}if(start>=day.AddDays(1)||end<=day)continue;
   var e=item;string label=(!String.IsNullOrEmpty(e.start.date)?"Toute la journée":start.ToString("HH:mm"))+" · "+e.summary;var button=Btn(label,delegate{EditGoogleEvent(e);},false,true);button.HorizontalContentAlignment=HorizontalAlignment.Left;button.ToolTip="Google Agenda";body.Children.Add(button);if(!String.IsNullOrWhiteSpace(e.description))body.Children.Add(T(e.description.Length>160?e.description.Substring(0,160)+"…":e.description,11,Muted,new Thickness(12,0,0,10)));
  }
 }
 void EditGoogleEvent(GoogleCalendarEvent existing){
  var calendar=calendarSources.FirstOrDefault(c=>c.id==store.Value.settings.GoogleCalendarId);if(calendar==null)return;bool writable=GoogleCalendarClient.CanWrite(calendar);DateTime start=existing==null?agendaDate.Date.AddHours(9):GoogleCalendarClient.LocalStart(existing),end=existing==null?start.AddHours(1):GoogleCalendarClient.LocalStart(new GoogleCalendarEvent{start=existing.end});bool all=existing!=null&&!String.IsNullOrEmpty(existing.start.date);
  StackPanel body,actions;var w=Dialog(existing==null?"Nouvel événement Google":"Événement Google",out body,out actions,680);
  var title=new TextBox{Text=existing==null?"":existing.summary,MaxLength=200,IsReadOnly=!writable};Field(body,"Titre",title);var allDay=new CheckBox{Content="Toute la journée",IsChecked=all,IsEnabled=writable};body.Children.Add(allDay);
  var date=new TextBox{Text=start.ToString("dd/MM/yyyy"),IsReadOnly=!writable};Field(body,"Début · JJ/MM/AAAA",date);var time=new TextBox{Text=start.ToString("HH:mm"),IsEnabled=writable&&!all};Field(body,"Heure du début",time);
  var until=new TextBox{Text=(all?end.AddDays(-1):end).ToString("dd/MM/yyyy"),IsReadOnly=!writable};Field(body,"Fin · JJ/MM/AAAA (dernier jour inclus si journée entière)",until);var endTime=new TextBox{Text=end.ToString("HH:mm"),IsEnabled=writable&&!all};Field(body,"Heure de fin",endTime);allDay.Click+=delegate{time.IsEnabled=endTime.IsEnabled=writable&&allDay.IsChecked!=true;};
  var notes=new TextBox{Text=existing==null?"":existing.description,AcceptsReturn=true,TextWrapping=TextWrapping.Wrap,Height=100,MaxLength=10000,IsReadOnly=!writable};Field(body,"Description",notes);var error=T("",12,AccentText);body.Children.Add(error);if(existing!=null&&!String.IsNullOrEmpty(existing.recurringEventId))body.Children.Add(T("La modification concerne cette occurrence de la série.",11,Muted));
  if(existing!=null&&writable)actions.Children.Add(Btn("Supprimer",delegate{if(MessageBox.Show("Supprimer cet événement de Google Agenda ?","Mon espace",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;w.DialogResult=true;GoogleOperation(async token=>{await CalendarApi.Delete(calendar.id,existing,token);calendarLoadedId="";googleMessage="Événement supprimé.";calendarAttempt=DateTime.MinValue;},"Suppression…");},false,true));
  actions.Children.Add(Btn("Fermer",delegate{w.DialogResult=false;},false,true));if(writable)actions.Children.Add(Btn("Enregistrer dans Google",delegate{string first,last;if(String.IsNullOrWhiteSpace(title.Text)||!ReadDate(date,true,out first)||!ReadDate(until,true,out last)||allDay.IsChecked!=true&&(!Schedule.ValidTime(time.Text)||!Schedule.ValidTime(endTime.Text))){error.Text="Vérifiez le titre, les dates et les heures.";return;}bool whole=allDay.IsChecked==true;DateTime a=Schedule.Day(first),b=Schedule.Day(last);if(whole)b=b.AddDays(1);else{a=a.Add(TimeSpan.Parse(time.Text));b=b.Add(TimeSpan.Parse(endTime.Text));}if(b<=a){error.Text="La fin doit suivre le début.";return;}string text=title.Text.Trim(),description=notes.Text;w.DialogResult=true;GoogleOperation(async token=>{await CalendarApi.Save(calendar.id,existing,text,description,a,b,whole,token);calendarLoadedId="";calendarAttempt=DateTime.MinValue;googleMessage="Événement enregistré dans Google Agenda.";},"Enregistrement dans Google Agenda…");},true));ShowWindow(w);
 }
 void OpenGoogleDocument(GoogleFilePin file){
  if(file.mimeType=="application/vnd.google-apps.folder"){Open(file.url);return;}
  GoogleOperation(async token=>{byte[] bytes=await GoogleClient.Document(file.id,file.mimeType,token);string extension=file.mimeType.StartsWith("application/vnd.google-apps.",StringComparison.Ordinal)?".pdf":Path.GetExtension(file.name);if(String.IsNullOrEmpty(extension))extension=file.mimeType=="application/pdf"?".pdf":".txt";if(!extension.All(c=>Char.IsLetterOrDigit(c)||c=='.'))throw new InvalidOperationException("Type de document invalide.");string folder=Path.Combine(store.Root,"DocumentCache");Directory.CreateDirectory(folder);folder=Path.Combine(folder,Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string name=String.Join("_",file.name.Split(Path.GetInvalidFileNameChars()));if(name.Length>100)name=name.Substring(0,100);if(!name.EndsWith(extension,StringComparison.OrdinalIgnoreCase))name+=extension;string path=Path.Combine(folder,"Document-"+name);File.WriteAllBytes(path,bytes);OpenDocument(path);googleMessage="Aperçu Google ouvert dans l’application.";},"Ouverture du document…");
 }
}
